/**
 * The Atlantic atlas: London and twelve US metros on a dotted world plate,
 * the instrument that opens every industry page's two-market section.
 *
 * Everything drawn on the plate is DERIVED from the coordinates and the two
 * plate definitions below — node positions, the HTML labels' percentage
 * offsets, every arc, each country's glow — because four things have to
 * agree on the geometry: the static dot layers generated by
 * `scripts/generate-atlas-dots.mjs`, the SVG paths, the label positions, and
 * the unit test. The plates are equirectangular on an explicit region, so a
 * city sits at a straight-line function of its latitude and longitude, and a
 * reader who checks Seattle against Miami finds the map honest.
 *
 * PLATES is duplicated in the generator script on purpose (it is a plain
 * `.mjs` that must not import TypeScript); `tests/unit/atlas-geometry.test.ts`
 * reads the generated files' viewBox back and fails the moment the two drift.
 */

export type AtlasRegion = {
  lat: { min: number; max: number };
  lng: { min: number; max: number };
};

export type AtlasPlateName = "wide" | "compact";

type AtlasPlateSpec = {
  region: AtlasRegion;
  /** Dot-grid counts, exactly as generated. */
  width: number;
  height: number;
};

/**
 * Where a city's label sits relative to its node. Chosen per city and per
 * plate so the east-coast cluster (Boston, New York and Philadelphia are
 * within ~20px of each other at 1200) never overprints.
 */
export type AtlasAnchor = "n" | "ne" | "e" | "se" | "s" | "sw" | "w" | "nw";

export type AtlasCity = {
  id: string;
  name: string;
  lat: number;
  lng: number;
  /** IANA zone name, printed in the city strip. */
  zone: "Eastern" | "Central" | "Mountain" | "Pacific" | "GMT";
  /**
   * How much of the plate a metro claims.
   *
   *   1 — labelled on both plates and linked to London by a drawn route.
   *   2 — labelled on the wide plate only, still linked.
   *   3 — plotted as a quiet node, never labelled, never linked.
   *
   * Twelve routes converging on one hub read as a fan, and thirteen labels
   * on a ~1100px plate piled the east coast three deep, so only the seven
   * best-spread metros carry a route and a name on the wide plate; a phone
   * plate resolves the US at ~150px across and keeps the first tier alone.
   * The city strip under the plate names every metro at every width, so
   * nothing a reader might search for leaves the page.
   */
  tier: 1 | 2 | 3;
  anchor: Record<AtlasPlateName, AtlasAnchor>;
};

/** viewBox units per dot-grid unit. Keeps stroke widths in whole numbers. */
export const ATLAS_SCALE = 10;

export const ATLAS_PLATES: Record<AtlasPlateName, AtlasPlateSpec> = {
  /** 192° × 68°: Alaska to the Caspian, the Sahel to Svalbard. */
  wide: {
    region: { lat: { min: 4, max: 72 }, lng: { min: -140, max: 52 } },
    width: 240,
    height: 85,
  },
  /** 148° × 56°: the North Atlantic alone, so a phone plate still resolves
   * the US coastlines, with eight degrees of Pacific so the west-coast labels
   * clear the plate's edge. */
  compact: {
    region: { lat: { min: 8, max: 64 }, lng: { min: -142, max: 6 } },
    width: 111,
    height: 42,
  },
};

export const ATLAS_LAYER_HREF: Record<
  AtlasPlateName,
  Record<"world" | "us" | "uk", string>
> = {
  wide: {
    world: "/maps/atlas-wide-world.svg",
    us: "/maps/atlas-wide-us.svg",
    uk: "/maps/atlas-wide-uk.svg",
  },
  compact: {
    world: "/maps/atlas-compact-world.svg",
    us: "/maps/atlas-compact-us.svg",
    uk: "/maps/atlas-compact-uk.svg",
  },
};

