/** The continental zones the twelve metros span, for the readout. */
export const US_TIME_ZONES = [...new Set(US_METROS.map((city) => city.zone))].length;

/** Metros that carry a drawn route to London: the first two tiers. */
export const LINKED_METROS: readonly AtlasCity[] = US_METROS.filter(
  (city) => city.tier <= 2,
);

export type AtlasPoint = { x: number; y: number };

/** One decimal: the resolution the plate is drawn at. More is noise in a path. */
const round1 = (n: number) => Math.round(n * 10) / 10;
const asPct = (value: number, span: number) =>
  `${String(round1((value / span) * 100))}%`;

/** Equirectangular: the same straight line the generator's dots sit on. */
export function projectOn(plate: AtlasPlateName, lat: number, lng: number): AtlasPoint {
  const { region, width, height } = ATLAS_PLATES[plate];
  const x = ((lng - region.lng.min) / (region.lng.max - region.lng.min)) * width;
  const y = ((region.lat.max - lat) / (region.lat.max - region.lat.min)) * height;
  return { x: round1(x * ATLAS_SCALE), y: round1(y * ATLAS_SCALE) };
}

/** How far north of its chord an arc bows, as a fraction of the chord. */
const ARC_LIFT = 0.22;
/** The arc's apex never rises above this fraction of the plate's height. */
const ARC_APEX_MIN = 0.08;

/**
 * The quadratic's control point: the chord's midpoint lifted north by a fixed
 * fraction of the chord, so a longer link bows more — the flat-projection
 * signature of a great circle — and every arc from one hub reads as one
 * family. The lift is clamped so the arc's apex (the curve at t = 0.5) stays
 * inside the plate: Seattle to London is long enough that an unclamped bow
 * would peak above the compact plate's top edge and be clipped.
 */
export function arcControl(
  from: AtlasPoint,
  to: AtlasPoint,
  plateHeight: number,
): AtlasPoint {
  const chord = Math.hypot(to.x - from.x, to.y - from.y);
  const midY = (from.y + to.y) / 2;
  // apex.y = (from.y + 2·ctrl.y + to.y) / 4, so the lowest control point that
  // keeps the apex at or below ARC_APEX_MIN · h is:
  const floor = (4 * ARC_APEX_MIN * plateHeight - from.y - to.y) / 2;
  return {
    x: round1((from.x + to.x) / 2),
    y: round1(Math.max(midY - chord * ARC_LIFT, floor)),
  };
}

export function arcPath(from: AtlasPoint, ctrl: AtlasPoint, to: AtlasPoint): string {
  return `M ${String(from.x)} ${String(from.y)} Q ${String(ctrl.x)} ${String(ctrl.y)} ${String(to.x)} ${String(to.y)}`;
}

/** The quadratic at t: the apex (t = 0.5) is what the geometry test checks. */
export function quadAt(
  from: AtlasPoint,
  ctrl: AtlasPoint,
  to: AtlasPoint,
  t: number,
): AtlasPoint {
  const u = 1 - t;
  return {
    x: round1(u * u * from.x + 2 * u * t * ctrl.x + t * t * to.x),
    y: round1(u * u * from.y + 2 * u * t * ctrl.y + t * t * to.y),
  };
}

export type AtlasNode = AtlasCity & {
  point: AtlasPoint;
  /** Percentage offsets for the HTML label over the plate box. */
  at: { x: string; y: string };
  /** Which anchor this plate uses. */
  side: AtlasAnchor;
  /** Whether this plate prints the label at all. */
  labelled: boolean;
  /** Whether a route is drawn between this node and London. */
  linked: boolean;
};

export type AtlasLink = {
  city: AtlasNode;
  ctrl: AtlasPoint;
  /**
   * London → city, so a `stroke-dashoffset` draw runs outward from the hub:
   * the routes power on as one signal leaving London for the metros.
   */
  path: string;
  /**
   * Draw order, 0 = the shortest route. The power-on staggers by this rather
   * than by array position, so the signal reaches the near coast first and
   * the Pacific last, the way a real fan-out would.
   */
  rank: number;
};

/** A soft ellipse of light under one country's dots: its glow. */
export type AtlasAura = { cx: number; cy: number; rx: number; ry: number };

export type AtlasPlate = {
  name: AtlasPlateName;
  w: number;
  h: number;
  viewBox: string;
  hub: AtlasNode;
  cities: AtlasNode[];
  links: AtlasLink[];
  aura: Record<"us" | "uk", AtlasAura>;
  layers: Record<"world" | "us" | "uk", string>;
};

function nodeOn(
  plate: AtlasPlateName,
  city: AtlasCity,
  w: number,
  h: number,
): AtlasNode {
  const point = projectOn(plate, city.lat, city.lng);
  return {
    ...city,
    point,
    at: { x: asPct(point.x, w), y: asPct(point.y, h) },
    side: city.anchor[plate],
    labelled: city.tier === 1 || (plate === "wide" && city.tier === 2),
    linked: city.tier <= 2,
  };
}

/** viewBox units per degree on this plate, for sizing the auras. */
function unitsPerDegree(plate: AtlasPlateName): number {
  const { region, width } = ATLAS_PLATES[plate];
  return (width * ATLAS_SCALE) / (region.lng.max - region.lng.min);
}

/**
 * The US glow is fitted to the metros' own extent — the ellipse that covers
 * the twelve nodes with a margin — so it lights the country the routes land
 * in, not an arbitrary disc. The UK is too small to fit to one node, so its
 * glow is a fixed few degrees around the island's centre.
 */
function aurasOn(
  plate: AtlasPlateName,
  cities: AtlasNode[],
): Record<"us" | "uk", AtlasAura> {
  const unit = unitsPerDegree(plate);
  const xs = cities.map((city) => city.point.x);
  const ys = cities.map((city) => city.point.y);
  const west = Math.min(...xs);
  const east = Math.max(...xs);
  const north = Math.min(...ys);
  const south = Math.max(...ys);
  const uk = projectOn(plate, 54.4, -2.8);
  return {
    us: {
      cx: round1((west + east) / 2),
      cy: round1((north + south) / 2),
      rx: round1(((east - west) / 2) * 1.3 + unit * 2),
      ry: round1(((south - north) / 2) * 1.35 + unit * 2.5),
    },
    uk: {
      cx: uk.x,
      cy: uk.y,
      rx: round1(unit * 6.5),
      ry: round1(unit * 6),
    },
  };
}

export function buildAtlasPlate(name: AtlasPlateName): AtlasPlate {
  const spec = ATLAS_PLATES[name];
  const w = spec.width * ATLAS_SCALE;
  const h = spec.height * ATLAS_SCALE;
  const hub = nodeOn(name, LONDON, w, h);
  const cities = US_METROS.map((city) => nodeOn(name, city, w, h));
  const linked = cities.filter((city) => city.linked);
  const byChord = [...linked].sort(
    (a, b) =>
      Math.hypot(hub.point.x - a.point.x, hub.point.y - a.point.y) -
      Math.hypot(hub.point.x - b.point.x, hub.point.y - b.point.y),
  );
  const links = linked.map((city) => {
    const ctrl = arcControl(hub.point, city.point, h);
    return {
      city,
      ctrl,
      path: arcPath(hub.point, ctrl, city.point),
      rank: byChord.indexOf(city),
    };
  });
  return {
    name,
    w,
    h,
    viewBox: `0 0 ${String(w)} ${String(h)}`,
    hub,
    cities,
    links,
    aura: aurasOn(name, cities),
    layers: ATLAS_LAYER_HREF[name],
  };
}

export const ATLAS_WIDE = buildAtlasPlate("wide");
export const ATLAS_COMPACT = buildAtlasPlate("compact");
